import glob,os,json,time,re
fs=sorted(glob.glob('/Users/kristinarash/.claude/projects/**/*.jsonl',recursive=True),key=os.path.getmtime)[-60:]
for f in fs:
    if os.path.getmtime(f)<time.time()-8*86400: continue
    for line in open(f,encoding='utf-8',errors='ignore'):
        if '"type":"user"' not in line.replace(' ',''): continue
        try: o=json.loads(line)
        except: continue
        c=o.get('message',{}).get('content')
        t=c if isinstance(c,str) else ' '.join(x.get('text','') for x in c if isinstance(x,dict) and x.get('type')=='text') if isinstance(c,list) else ''
        if re.search(r'maintenance',t,re.I) and len(t)<3000 and 'system-reminder' not in t[:50]:
            print(time.strftime('%m-%d %H:%M',time.localtime(os.path.getmtime(f))),os.path.basename(f)[:8],'|',t[:600].replace('\n',' '));print('--')

