5:function Invoke-MeetingSync {
6:    param([string]$VaultDir = "/Users/kristinarash/SecondBrain/Inbox/meetings")
8:    Show-Section "Meeting Sync"
9:    $ff = Get-Command fireflies-pp-cli -ErrorAction SilentlyContinue
10:    if (-not $ff) { Write-Host "fireflies-pp-cli not found on PATH; skipped."; return $null }
12:    $vaultDir = $VaultDir
13:    New-Item -ItemType Directory -Force -Path $vaultDir | Out-Null
14:    $statePath = Join-Path $vaultDir ".sync-state.json"
15:    if (-not (Test-Path -LiteralPath $statePath)) {
16:        '{"exports":{}}' | Set-Content -LiteralPath $statePath -Encoding UTF8
17:    }
19:    # A failure here used to print and return, so the cadence still logged
20:    # "cadence OK"; it failed silently every morning until 2026-10-23.
21:    # .errors.log is shown at every session start.
22:    $reportFailure = {
23:        param([string]$Message)
24:        Write-Host $Message
25:        $errLog = Join-Path $HOME ".claude/global-memory/transcripts/.errors.log"
26:        if (Test-Path -LiteralPath (Split-Path -Parent $errLog)) {
27:            Add-Content -LiteralPath $errLog -Value "$(Get-Date -Format 'yyyy-MM-dd HH:mm') keystone meeting-sync: $Message"
28:        }
29:    }
31:    # launchd runs pwsh -NoProfile, so the ~/.zshrc Keychain export never
32:    # happens. Read the same Keychain item directly (works under launchd,
33:    # tested 2026-10-23). Do not use `auth set-token` (name-meetings SKILL.md).
34:    if ($IsMacOS -and -not $env:FIREFLIES_API_KEY) {
35:        $key = & /usr/bin/security find-generic-password -s FIREFLIES_API_KEY -a $env:USER -w 2>$null
36:        if ($LASTEXITCODE -eq 0 -and $key) { $env:FIREFLIES_API_KEY = ([string]$key).Trim() }
37:    }
39:    $syncOut = @(& fireflies-pp-cli sync --agent 2>&1)
40:    $syncExit = $LASTEXITCODE
41:    $syncOut | ForEach-Object { Write-Host $_ }
42:    if ($syncExit -ne 0) {
43:        & $reportFailure "fireflies-pp-cli sync failed (exit $syncExit); skipping export this run."
44:        return $null
45:    }
46:    # A rejected key still exits 0; it only shows as sync_error events.
47:    $syncErrors = @($syncOut | Where-Object { "$_" -match '"event"\s*:\s*"sync_error"' })
48:    if ($syncErrors.Count -gt 0) {
49:        & $reportFailure "fireflies-pp-cli sync reported $($syncErrors.Count) sync_error event(s): a bad or expired FIREFLIES_API_KEY, or a Fireflies API error."
50:    }
