# The generic-title list in ~/.claude/skills/name-meetings/REFERENCE.md ("Generic-title patterns").
# Fail-open: an error here means "not generic", so the meeting still exports.
function Test-GenericMeetingTitle {
    param([string]$Title)
    try {
        $t = ([string]$Title).Trim().ToLowerInvariant()
        if ($t.Length -lt 5) { return $true }
        $patterns = @(
            '^(meeting|call|recording|untitled|zoom meeting|teams meeting|microsoft teams meeting|google meet|meeting on|call with)$',
            '^(meeting )?\d{4}-\d{2}-\d{2}$',
            '^\d{1,2}/\d{1,2}/\d{4}$',
            '^[a-z]{3} \d{1,2}, \d{1,2}:\d{2} (am|pm)$',
            '^\S+@\S+ - .+ - untitled$',
            '^\d+ (people|attendees)$'
        )
        foreach ($p in $patterns) { if ($t -match $p) { return $true } }
        return $false
    } catch { return $false }
}

