# Hold a generic-titled meeting back for its first $Days days so the meeting-sync skill can
# rename it; after that, export it as it is so it never ages out of the 14-day find window.
# Fail-open: an unreadable date exports.
function Test-HoldGenericMeeting {
    param($Transcript, [int]$Days = 7, [datetime]$Now = (Get-Date))
    if (-not (Test-GenericMeetingTitle $Transcript.title)) { return $false }
    try {
        $when = $Transcript.dateString
        if ($when -isnot [datetime]) { $when = [datetime]::Parse([string]$when, [Globalization.CultureInfo]::InvariantCulture) }
        return (($Now.ToUniversalTime() - $when.ToUniversalTime()).TotalDays -lt $Days)
    } catch { return $false }
}

