# tests/keystone-meeting-sync-generic.ps1
# Test-GenericMeetingTitle against the name-meetings REFERENCE.md list. Loads the one function by AST;
# runs no sync and no CLI.
$ErrorActionPreference = "Stop"
function Assert-True($Condition, $Message) { if (-not $Condition) { throw $Message } }
$repoRoot = Resolve-Path (Join-Path $PSScriptRoot "..")
$ast = [System.Management.Automation.Language.Parser]::ParseFile((Join-Path $repoRoot "scripts/keystone.ps1"), [ref]$null, [ref]$null)
foreach ($name in 'Test-GenericMeetingTitle', 'Test-HoldGenericMeeting') {
    $fn = $ast.FindAll({ $args[0] -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $args[0].Name -eq $name }, $true) | Select-Object -First 1
    Assert-True ($null -ne $fn) "$name not found in keystone.ps1"
    . ([scriptblock]::Create($fn.Extent.Text))
}

