    'eric.rash11@gmail.com - Tue, 28 Jul 2026 10:16:54 CDT - Untitled', 'abc')
$curated = @('2026-01-30_BAIR_Steering_Approval', 'KB_TechSync_10282026', 'StaffMeet_10222026', 'SA_Leadership_10192026',
    'Meeting with Kenny about OKRs', 'Call with Joe re RTP dial card')
foreach ($t in $generic) { Assert-True (Test-GenericMeetingTitle $t) "should be generic: '$t'" }
foreach ($t in $curated) { Assert-True (-not (Test-GenericMeetingTitle $t)) "should be curated: '$t'" }
Write-Host "keystone meeting-sync generic-title tests passed ($($generic.Count) generic, $($curated.Count) curated)"

